head.html:
#rc-tool{border:1px solid rgba(0,0,0,.12);border-radius:14px;padding:22px;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.06)}
.rc-sec{margin:0 0 18px}
.rc-sec-h{font-size:15px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;opacity:.65;margin:0 0 8px}
.rc-q{display:flex;gap:12px;align-items:flex-start;padding:10px 0;border-top:1px solid rgba(0,0,0,.07)}
.rc-q-txt{flex:1;font-size:15px;line-height:1.5}
.rc-tag{display:inline-block;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;padding:2px 7px;border-radius:99px;margin-left:6px;vertical-align:middle}
.rc-tag-c{background:#fde8e1;color:#b4531a}
.rc-tag-i{background:#e8f0fe;color:#1a56b4}
.rc-btns{display:flex;gap:6px;flex-shrink:0}
.rc-b{font:13px inherit;padding:6px 14px;border-radius:99px;border:1px solid rgba(0,0,0,.2);background:#fff;cursor:pointer}
.rc-b.on-yes{background:#2fae5d;color:#fff;border-color:#2fae5d}
.rc-b.on-no{background:#b4531a;color:#fff;border-color:#b4531a}
.rc-res{margin-top:18px;padding:18px;border-radius:12px;background:#f7f7f7}
.rc-score{font-size:34px;font-weight:700;line-height:1.1}
.rc-verdict{font-size:16px;margin-top:4px}
.rc-fix{margin-top:12px;font-size:14px;line-height:1.6}
.rc-fix-li{margin:6px 0 6px 18px}
.rc-bar{height:8px;border-radius:99px;background:rgba(0,0,0,.08);margin-top:12px;overflow:hidden}
.rc-fill{height:100%;width:0;background:#2fae5d;transition:width .2s}
.rc-row{display:flex;gap:10px;margin-top:14px;flex-wrap:wrap}
.rc-cta{display:inline-block;padding:10px 18px;border-radius:99px;background:#2fae5d;color:#fff;text-decoration:none;font-weight:600;font-size:14px}
.rc-reset{font:13px inherit;padding:8px 14px;border-radius:99px;border:1px solid rgba(0,0,0,.2);background:#fff;cursor:pointer}
